        return (sample * PPQ / samplesPerBeat(bpm)).roundToLong()
    }

    private fun samplesPerBeat(bpm: Float): Double {
        require(bpm > 0f) { "BPM must be positive" }
        return (60.0 / bpm) * sampleRate
    }
}

