@Composable
private fun TimelineRuler(
    barWidthPx: Float,
    totalBars: Int,
    modifier: Modifier = Modifier
) {
    val density = LocalDensity.current
    Box(modifier = modifier) {
        for (b in 0 until totalBars) {
            Text(
                text = "${b + 1}",
                color = TextMuted,
                fontSize = 8.sp,
                fontWeight = FontWeight.Bold,
