        // Meter + Fader
        Row(
            modifier = Modifier.height(160.dp),
            verticalAlignment = Alignment.Bottom
        ) {
            LevelMeter(
                level = channel.level,
                modifier = Modifier
                    .width(10.dp)
                    .fillMaxHeight()
