            Spacer(Modifier.width(4.dp))
            VerticalFader(
                value = channel.faderDb,
                onValueChange = onFaderChange,
                onMidiLearn = onMidiLearnFader,
                modifier = Modifier
                    .width(44.dp)
                    .fillMaxHeight()
            )
        }

        Spacer(Modifier.height(4.dp))

        // Fader value readout
        Text(
            text = "%.1f".format(channel.faderDb),
            color = TextSecondary,
            fontSize = 8.sp,
            fontWeight = FontWeight.Bold
