                    val ledAlpha = (0.1f + value * 0.5f).coerceIn(0f, 1f)
                    drawCircle(
                        color = ledColor.copy(alpha = ledAlpha),
                        radius = knobRadius + 2f,
                        center = Offset(cx, cy),
                        style = Stroke(width = 2f)
                    )
                }

                // 8. MIDI learn selected highlight
                if (isSelected) {
                    drawCircle(
                        color = MidiLearnGlow,
                        radius = knobRadius + 3f,
                        center = Offset(cx, cy),
                        style = Stroke(width = 2f)
                    )
                }
            }

            // Tooltip overlay
            if (showTooltip) {
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .pointerInput(Unit) {
                            detectTapGestures { showTooltip = false }
                        },
                    contentAlignment = Alignment.Center
                ) {
                    Box(
                        modifier = Modifier
                            .background(Color(0xE6000000), shape = androidx.compose.foundation.shape.RoundedCornerShape(4.dp))
                            .padding(horizontal = 6.dp, vertical = 3.dp)
                    ) {
                        Text(
                            text = "$label: $valueDisplay",
                            color = TextPrimary,
                            fontSize = 9.sp
                        )
                    }
                }
            }
        }

        // Label below knob
        if (label.isNotEmpty()) {
            Text(
                text = label,
                color = TextSecondary,
                fontSize = 8.sp,
                fontWeight = FontWeight.Medium,
                letterSpacing = 0.3.sp,
                maxLines = 1
            )
        }

        // Value display
        if (valueDisplay.isNotEmpty()) {
            Text(
                text = valueDisplay,
                color = accentColor,
                fontSize = 10.sp,
                fontWeight = FontWeight.Bold,
                fontFamily = FontFamily.Monospace
            )
        }
    }
}

