/**
 * Horizontal slider. (Unchanged — kept as-is per spec.)
 */
@Composable
fun SynthSlider(
    value: Float,
    onValueChange: (Float) -> Unit,
    modifier: Modifier = Modifier,
    label: String = "",
    accentColor: Color = KnobCyan
) {
