    }

    fun toggleNoteRepeat() {
        val enabled = !_uiState.value.noteRepeatEnabled
        _uiState.update { it.copy(noteRepeatEnabled = enabled) }
        if (!enabled) {
            noteRepeatJobs.values.forEach { it.cancel() }
